/// <summary>
/// 126687 2nd API to communicate during submission / validation / posting of the journal
/// </summary>
class MET_CheckJournalPostStatusService
{
}

Method.Source:
    public MET_CheckJournalPostStatusResponse create(MET_CheckJournalPostStatusRequest _request)
    {
        JournalId               journalNum;
        LedgerJournalTable      lJournalTable;
        boolean                 comment,UserId;
        var response = new MET_CheckJournalPostStatusResponse();

        try
        {
            journalNum = _request.parmJournalId();

            changecompany(_request.parmDataAreaId())
            {
                select Posted, WorkflowApprovalStatus,METErrorLog from lJournalTable
                    where lJournalTable.JournalNum == journalNum;

                if(lJournalTable.Posted == NoYes::Yes)
                {
                    response.parmJournalNum(journalNum);
                    response.parmSuccess(true);
                    response.parmWorkflowStatus(enum2Str(lJournalTable.WorkflowApprovalStatus));
                    response.parmApprovedBy(this.getApprovedBy(journalNum, _request.parmDataAreaId()));
                    response.parmrejectedBy(this.getRejectedBy(journalNum, _request.parmDataAreaId()));
                    response.parmApprovedByName(this.getApprovedByName(journalNum, _request.parmDataAreaId()));
                    response.parmRejectedByName(this.getRejectedByName(journalNum,_request.parmDataAreaId()));
                    response.parmApprovalComment(this.getApprovalWorkflowComment(journalNum,_request.parmDataAreaId()));
                    response.parmRejectedComment(this.getRejectedWorkflowComment(journalNum,_request.parmDataAreaId()));

                    if((enum2Str(lJournalTable.WorkflowApprovalStatus) == '@MET:METApproved')
                        && (this.getApprovedBy(journalNum, _request.parmDataAreaId()) == ""))
                    {
                        response.parmautoWorkflowApproval('@MET:Yes');
                    }
                    else
                    {
                        response.parmautoWorkflowApproval('@MET:No');
                    }
                }
                else
                {
                    response.parmJournalNum(journalNum);
                    response.parmSuccess(false);
                    response.parmWorkflowStatus(enum2Str(lJournalTable.WorkflowApprovalStatus));
                    if(lJournalTable.METErrorLog)
                    {
                        response.parmErrorMessage(lJournalTable.METErrorLog);
                    }
                    else
                    {
                        response.parmErrorMessage(lJournalTable.Log);
                    }
                    response.parmApprovedBy(this.getApprovedBy(journalNum, _request.parmDataAreaId()));
                    response.parmrejectedBy(this.getRejectedBy(journalNum, _request.parmDataAreaId()));
                    response.parmApprovedByName(this.getApprovedByName(journalNum, _request.parmDataAreaId()));
                    response.parmRejectedByName(this.getRejectedByName(journalNum,_request.parmDataAreaId()));
                    response.parmApprovalComment(this.getApprovalWorkflowComment(journalNum,_request.parmDataAreaId()));
                    response.parmRejectedComment(this.getRejectedWorkflowComment(journalNum,_request.parmDataAreaId()));

                    if((enum2Str(lJournalTable.WorkflowApprovalStatus) == '@MET:METApproved')
                        && (this.getApprovedBy(journalNum, _request.parmDataAreaId()) == ""))
                    {
                        response.parmautoWorkflowApproval('@MET:Yes');
                    }
                    else
                    {
                        response.parmautoWorkflowApproval('@MET:No');
                    }
                }
            }
            
        }
        catch (Exception::CLRError)
        {
            System.Exception interopException = CLRInterop::getLastException();

            response.parmJournalNum(journalNum);
            response.parmSuccess(false);
            response.parmWorkflowStatus(enum2Str(lJournalTable.WorkflowApprovalStatus));
            response.parmErrorMessage(lJournalTable.METErrorLog);
        }

        return response;
    }

    public WorkflowComment getRejectedWorkflowComment(JournalId  _journalId, str _dataAreaId)
    {
        WorkflowTrackingTable           workflowTrackingTable;
        WorkflowTrackingStatusTable     workflowTrackingStatusTable;
        WorkflowTrackingCommentTable    workflowTrackingCommentTable;
        LedgerJournalTable              ledgerJournalTable;

        ledgerJournalTable = LedgerJournalTable::find(_journalId);

        select ContextCompanyId, ContextTableId, ContextRecId from workflowTrackingStatusTable
        where workflowTrackingStatusTable.ContextCompanyId    == _dataAreaId
           && workflowTrackingStatusTable.ContextTableId      == ledgerJournalTable.TableId
           && workflowTrackingStatusTable.ContextRecId        == ledgerJournalTable.RecId
        join firstonly TrackingId, CreatedDateTime from workflowTrackingTable order by CreatedDateTime desc
            where workflowTrackingTable.WorkflowTrackingStatusTable == workflowTrackingStatusTable.RecId
                && workflowTrackingTable.TrackingType == WorkflowTrackingType::Rejection
        join Comment from workflowTrackingCommentTable
            where workflowTrackingCommentTable.WorkflowTrackingTable == workflowTrackingTable.RecId;

        return workflowTrackingCommentTable.Comment;
    }

    public WorkflowComment getApprovalWorkflowComment(JournalId  _journalId, str _dataAreaId)
    {
        WorkflowTrackingTable           workflowTrackingTable;
        WorkflowTrackingStatusTable     workflowTrackingStatusTable;
        WorkflowTrackingCommentTable    workflowTrackingCommentTable;
        LedgerJournalTable              ledgerJournalTable;

        ledgerJournalTable = LedgerJournalTable::find(_journalId);

        select ContextCompanyId, ContextTableId, ContextRecId from workflowTrackingStatusTable
        where workflowTrackingStatusTable.ContextCompanyId    == _dataAreaId
           && workflowTrackingStatusTable.ContextTableId      == ledgerJournalTable.TableId
           && workflowTrackingStatusTable.ContextRecId        == ledgerJournalTable.RecId
        join firstonly TrackingId, CreatedDateTime from workflowTrackingTable order by CreatedDateTime desc
            where workflowTrackingTable.WorkflowTrackingStatusTable == workflowTrackingStatusTable.RecId
            && workflowTrackingTable.TrackingType == WorkflowTrackingType::Approval
        join Comment from workflowTrackingCommentTable
            where workflowTrackingCommentTable.WorkflowTrackingTable == workflowTrackingTable.RecId;

        return workflowTrackingCommentTable.Comment;
    }

    public str getApprovedBy(JournalId  _journalId, str _dataAreaId)
    {
        WorkflowTrackingTable           workflowTrackingTable;
        WorkflowTrackingStatusTable     workflowTrackingStatusTable;
        WorkflowTrackingCommentTable    workflowTrackingCommentTable;
        LedgerJournalTable              ledgerJournalTable;

        ledgerJournalTable = LedgerJournalTable::find(_journalId);

        select ContextCompanyId, ContextTableId, ContextRecId from workflowTrackingStatusTable
        where workflowTrackingStatusTable.ContextCompanyId    == _dataAreaId
           && workflowTrackingStatusTable.ContextTableId      == ledgerJournalTable.TableId
           && workflowTrackingStatusTable.ContextRecId        == ledgerJournalTable.RecId
        join firstonly TrackingId, CreatedDateTime,User from workflowTrackingTable order by CreatedDateTime desc
            where workflowTrackingTable.WorkflowTrackingStatusTable == workflowTrackingStatusTable.RecId
            && workflowTrackingTable.TrackingType == WorkflowTrackingType::Approval;
        

        return workflowTrackingTable.User;
    }

